201	// belowMinimumRefTarget は below_minimum_ref の参照先の指摘を返す。参照先にできるのは、
202	// この回 (添字 ri) より前の回の、必要度を判定して下限未満にした指摘 (B1) だけ。
203	// 判定を省略した指摘 (B2) は必要度を持たないので、参照先にしない。
204	func belowMinimumRefTarget(doc *recordDoc, ri int, ref *recordBelowMinimumRef) (*recordFinding, string) {
205		if ref.Run < 1 || ref.Run > ri {
206			return nil, fmt.Sprintf("below_minimum_ref の run %d は、この回より前の回ではありません (この回は %d 回目)", ref.Run, ri+1)
207		}
208		findings := doc.Runs[ref.Run-1].Findings
209		for i := range findings {
210			if findings[i].ID != ref.Finding {
211				continue
212			}
213			t := &findings[i]
214			if t.Verdict != "below_minimum" || fixNecessityRank(t.FixNecessity) == 0 {
215				return nil, fmt.Sprintf("below_minimum_ref の参照先 (%d 回目の id %d) は、必要度を判定して下限未満にした指摘ではありません (verdict %q / fix_necessity %q)",
216					ref.Run, ref.Finding, t.Verdict, t.FixNecessity)
217			}
218			return t, ""
219		}
220		return nil, fmt.Sprintf("below_minimum_ref の finding %d は %d 回目の findings にありません", ref.Finding, ref.Run)
221	}
