223	// recordBelowMinimumRefProblems は指摘 1 件の below_minimum_ref と、それに関わるキーを検査する。
224	func recordBelowMinimumRefProblems(doc *recordDoc, ri int, fd recordFinding) []string {
225		var problems []string
226		add := func(format string, args ...any) {
227			problems = append(problems, fmt.Sprintf(format, args...))
228		}
229		ref := fd.BelowMinimumRef
230		if ref == nil {
231			if fd.Origin == "prior_below_minimum" {
232				add("origin が prior_below_minimum なのに below_minimum_ref がありません (足した指摘は、前の回のどの指摘かを書く)")
233			}
234			return problems
235		}
236		target, msg := belowMinimumRefTarget(doc, ri, ref)
237		if msg != "" {
238			add("%s", msg)
239		}
240		switch ref.LineCheck {
241		case "holds", "not-holds", "unverifiable":
242		default:
243			add("below_minimum_ref.line_check は holds / not-holds / unverifiable のいずれか: %q", ref.LineCheck)
244		}
245		if ref.LineReason == "" {
246			add("below_minimum_ref.line_reason がありません (対象の行が変わっていないかの結果の理由)")
247		}
248		if !judgmentOmitted(fd) {
249			return problems
250		}
251		// 判定を省略した指摘 (A3・B2)。分類・被害者・帰結・根拠の検証・ゲート・必要度は書かない。
252		// 書いてあると、参照先の値と、この指摘の値のどちらを読むのかが決まらない。
253		for _, kv := range []struct {
254			key     string
255			written bool
256		}{
257			{"category", fd.Category != ""},
258			{"audience", fd.Audience != ""},
259			{"audience_initial", fd.AudienceInitial != ""},
260			{"consequence", fd.Consequence != recordConsequence{}},
261			{"premise_check", fd.PremiseCheck != recordPremise{}},
262			{"gates_fired", len(fd.GatesFired) > 0},
263			{"prior_defect", fd.PriorDefect != nil},
264			{"fix_necessity", fd.FixNecessity != ""},
265			{"fix_necessity_reason", fd.FixNecessityReason != nil},
266		} {
267			if kv.written {
268				add("判定を省略した指摘 (below_minimum_ref.line_check が holds) では %s を書かない (参照先の指摘のものを読む)", kv.key)
269			}
270		}
271		if target == nil {
272			return problems
273		}
274		// D12: 参照先の必要度が、この回の下限以上なら採択 (A3)、満たなければ下限未満 (B2)。
275		want := "adopted"
276		if fixNecessityBelow(target.FixNecessity, doc.Runs[ri].MinFixNecessity) {
277			want = "below_minimum"
278		}
279		if fd.Verdict != want {
280			minimum := doc.Runs[ri].MinFixNecessity
281			if minimum == "" {
282				minimum = "無し"
283			}
284			add("判定を省略した指摘の verdict は、参照先の必要度 %s と回の下限 %s から %s に決まりますが、%q です",
285				target.FixNecessity, minimum, want, fd.Verdict)
286		}
287		return problems
288	}
