290	// recordPriorBelowMinimumProblems は、回 (添字 ri) に足すべき下限未満の指摘が、足されているかを
291	// 検査する。それより前の回の、残っている下限未満の指摘 (必要度を判定して下限未満にした指摘で、
292	// この回より前の回の指摘が参照して、判定し直しても採択にしてもいないもの) のうち、必要度がこの回の
293	// 下限以上のもの (下限が無い回ではすべて) は、この回の指摘として足す (record-schema.md の
294	// 「下限未満の指摘の参照」)。足し忘れると、下限を下げても、その指摘は採択にならず直されないまま残る。
295	// 足したかどうかは、この回の指摘の below_minimum_ref が参照しているかで見る。呼び出し元は、
296	// 記録の最後の回についてだけ呼ぶ。
297	func recordPriorBelowMinimumProblems(doc *recordDoc, ri int) []string {
298		type key struct{ run, finding int }
299		remaining := map[key]string{} // 残っている下限未満の指摘と、その必要度
300		var order []key
301		for pi := 0; pi < ri; pi++ {
302			for _, fd := range doc.Runs[pi].Findings {
303				if ref := fd.BelowMinimumRef; ref != nil && !(judgmentOmitted(fd) && fd.Verdict == "below_minimum") {
304					// 判定し直したか、採択 (A3) にした。参照先は残っていない。
305					delete(remaining, key{ref.Run, ref.Finding})
306				}
307				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
308					k := key{pi + 1, fd.ID}
309					remaining[k] = fd.FixNecessity
310					order = append(order, k)
311				}
312			}
313		}
314		referenced := map[key]bool{}
315		for _, fd := range doc.Runs[ri].Findings {
316			if ref := fd.BelowMinimumRef; ref != nil {
317				referenced[key{ref.Run, ref.Finding}] = true
318			}
319		}
320		minimum := doc.Runs[ri].MinFixNecessity
321		var problems []string
322		for _, k := range order {
323			necessity, ok := remaining[k]
324			if !ok || referenced[k] || fixNecessityBelow(necessity, minimum) {
325				continue
326			}
327			// 下限が列挙に無い値のときは、比べられないので報告しない (列挙の誤りは別に報告する)。
328			if minimum != "" && fixNecessityRank(minimum) == 0 {
329				continue
330			}
331			// 「無い」には「のに」が、「以上」には「なのに」が付くので、句ごとに「のに」まで書く。
332			limit := "この回に下限が無いのに"
333			if minimum != "" {
334				limit = "この回の下限 " + minimum + " 以上なのに"
335			}
336			problems = append(problems, fmt.Sprintf(
337				"残っている下限未満の指摘 (%d 回目の id %d。必要度 %s) が、%s、この回の findings に足されていません (origin: prior_below_minimum と below_minimum_ref を書いて足す)",
338				k.run, k.finding, necessity, limit))
339		}
340		return problems
341	}
