355	// renderFixNecessityCounts は推移の表の必要度の 3 列 (Must・Should・Could) を返す。
356	// 判定に関わらず、その回で必要度が分かる指摘を数える。fix_necessity_reason を必須にする回
357	// (recordFixNecessityFirstRun) より前の回 (必須にする回が無い記録ではすべての回) は「—」にする。0 と書くと、
358	// 必要度を判定して 0 件だったように読めるため。
359	func renderFixNecessityCounts(doc *recordDoc, ri, firstRun int) []string {
360		if firstRun < 0 || ri < firstRun {
361			return []string{"—", "—", "—"}
362		}
363		counts := map[string]int{}
364		for _, fd := range doc.Runs[ri].Findings {
365			counts[findingFixNecessity(doc, ri, fd)]++
366		}
367		return []string{
368			fmt.Sprint(counts["must"]), fmt.Sprint(counts["should"]), fmt.Sprint(counts["could"]),
369		}
